INSERT INTO `careers` VALUES (3,'Accounting Officer','Accounting Officer','<ul>\n<li>&nbsp; &nbsp; &nbsp; &nbsp; Record sale &amp; purchase slip in excel &amp; system.</li>\n<li>&nbsp; &nbsp; &nbsp; &nbsp; File/ store related documents.</li>\n<li>&nbsp; &nbsp; &nbsp; &nbsp; Record trading transaction with supplier</li>\n<li>&nbsp; &nbsp; &nbsp; &nbsp; Assist tax declarations.</li>\n<li>&nbsp; &nbsp; &nbsp; &nbsp; Record daily operation expense to system.</li>\n<li>&nbsp; &nbsp; &nbsp; &nbsp; Entry any accounting data into system.</li>\n<li>&nbsp; &nbsp; &nbsp; &nbsp; Prepare invoice to customers.</li>\n<li>&nbsp; &nbsp; &nbsp; &nbsp; Update accounts receivable &amp; payable.</li>\n<li><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol; mso-bidi-language: KHM;\"><span style=\"mso-list: Ignore;\"><span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></span></span><span style=\"font-family: \'Trebuchet MS\',sans-serif; mso-bidi-language: KHM;\">Perform cash collection/settlement transaction.</span></li>\n<li>&nbsp; &nbsp; &nbsp; &nbsp; Assist senior accountant and accounting supervisor in daily operation transactions.</li>\n<li>&nbsp; &nbsp; &nbsp; &nbsp;Other tasks assigned by CFO.</li>\n</ul>','<ul style=\"list-style-type: square;\">\n<li class=\"MsoListParagraph\" style=\"text-indent: -18pt;\">&nbsp; &nbsp; &nbsp; Record sale &amp; purchase slip in excel &amp; system.</li>\n<li class=\"MsoListParagraph\" style=\"text-indent: -18pt;\">&nbsp; &nbsp; &nbsp; &nbsp; File/ store related documents.</li>\n<li class=\"MsoListParagraph\" style=\"text-indent: -18pt;\">&nbsp; &nbsp; &nbsp; &nbsp; Record trading transaction with supplier</li>\n<li class=\"MsoListParagraph\" style=\"text-indent: -18pt;\">&nbsp; &nbsp; &nbsp; &nbsp; Assist tax declarations.</li>\n<li class=\"MsoListParagraph\" style=\"text-indent: -18pt;\">&nbsp; &nbsp; &nbsp; &nbsp; Record daily operation expense to system.</li>\n<li class=\"MsoListParagraph\" style=\"text-indent: -18pt;\">&nbsp; &nbsp; &nbsp; &nbsp; Entry any accounting data into system.</li>\n<li class=\"MsoListParagraph\" style=\"text-indent: -18pt;\">&nbsp; &nbsp; &nbsp; &nbsp; Prepare invoice to customers.</li>\n<li class=\"MsoListParagraph\" style=\"text-indent: -18pt;\">&nbsp; &nbsp; &nbsp; &nbsp; Update accounts receivable &amp; payable.</li>\n<li class=\"MsoListParagraph\" style=\"text-indent: -18pt;\"><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol; mso-bidi-language: KHM;\"><span style=\"mso-list: Ignore;\"><span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></span></span><!--[endif]--><span style=\"font-family: \'Trebuchet MS\',sans-serif; mso-bidi-language: KHM;\">Perform cash collection/settlement transaction.</span></li>\n<li class=\"MsoListParagraph\" style=\"text-indent: -18pt;\">&nbsp; &nbsp; &nbsp; &nbsp; Assist senior accountant and accounting supervisor in daily operation transactions.</li>\n<li class=\"MsoListParagraph\" style=\"text-indent: -18pt;\">&nbsp; &nbsp; &nbsp; &nbsp;Other tasks assigned by CFO.</li>\n</ul>','<ul>\n<li><!-- [if !supportLists]--><span style=\"font-family: \'Trebuchet MS\',sans-serif;\">Year 3 of bachelor in related field (Law, Banking, Finance, Accounting, ...).</span></li>\n<li>Good with numbers and figures and an analytical acumen.</li>\n<li>Good understanding of accounting and financial reporting principles and practices.</li>\n<li>Knowledge of computer software &amp; Microsoft excel.</li>\n<li>Ability to work under pressure highly self-motivated.</li>\n</ul>','<ul>\n<li><span style=\"font-family: \'Trebuchet MS\',sans-serif;\">Year 3 of bachelor in related field (Law, Banking, Finance, Accounting, ...).</span></li>\n<li>Good with numbers and figures and an analytical acumen.</li>\n<li>Good understanding of accounting and financial reporting principles and practices.</li>\n<li>Knowledge of computer software &amp; Microsoft excel.</li>\n<li>Ability to work under pressure highly self-motivated.</li>\n</ul>','Head Office, Phnom Penh','','2026-04-30','',2,0,'2026-02-06 03:05:08','2026-04-24 09:05:55',NULL,NULL,NULL,NULL,NULL,NULL),(4,'Sales Officer','Sales Officer','<ul>\n<li>Build and maintain strong relationships with new and existing clients to increase transaction volume and customer loyalty.</li>\n<li>Provide clients with updated goods price information, comparative advantages, and transaction terms.</li>\n<li>Implement security measures and ensure compliance with AML/KYC procedures and other relevant regulations.</li>\n<li>Coordinate with settlement and finance departments to ensure smooth completion of transactions.</li>\n<li>Other task will be assigned by Supervisor</li>\n</ul>','<ul>\n<li>Build and maintain strong relationships with new and existing clients to increase transaction volume and customer loyalty.</li>\n<li>Provide clients with updated goods price information, comparative advantages, and transaction terms.</li>\n<li>Implement security measures and ensure compliance with AML/KYC procedures and other relevant regulations.</li>\n<li>Coordinate with settlement and finance departments to ensure smooth completion of transactions.</li>\n<li>Other task will be assigned by Supervisor</li>\n</ul>','<ul>\n<li>Studying Bachelor&rsquo;s degree in Economics, Finance, or a related field (or equivalent professional experience).</li>\n<li>Experience in sales, customer services, or related financial services.</li>\n<li>Strong interpersonal and communication skills to explain clearly.</li>\n<li>Solid knowledge of currency markets, basic financial principles, and calculations.</li>\n<li>High level of integrity, accuracy, and accountability in handling financial data and transactions.</li>\n</ul>','<ul>\n<li>Studying Bachelor&rsquo;s degree in Economics, Finance, or a related field (or equivalent professional experience).</li>\n<li>Experience in sales, customer services, or related financial services.</li>\n<li>Strong interpersonal and communication skills to explain clearly.</li>\n<li>Solid knowledge of currency markets, basic financial principles, and calculations.</li>\n<li>High level of integrity, accuracy, and accountability in handling financial data and transactions.</li>\n</ul>','Head Office, Phnom Penh','No. 31, St. 286, Sangkat Olympic, Khan Boeng Keng Kang, Phnom Penh, Cambodia.','2026-05-31','',1,0,'2026-03-17 09:49:14','2026-09-15 09:18:46','sales-officer','','','','',''),(5,'PA to Managing Director','PA to Managing Director','<p>1. Reminder of daily weekly meeting and schedules.<br>2. Take over some of my work while I am away on trips. E.g. if I have construction project. Keep follow up and updates; if I have loan deal, keep follow up and updates.<br>3. Prepare driver when I need to leave or when driver not available drive on behave of driver.<br>4. Prepare meeting minutes<br>5. Make booking and reservation for restaurants, hotel, air ticket and others.<br>6. Have good khmer, English and chinese language speaking reading and writing additional language is bonus.<br>8. High level of organization skills<br>9. Take initiative to make plan or action when think require.<br>10. Thinking level at least business from supervisor level.<br>11. Must look presentable and professional.<br>12. Able to know modern AL ( bonus) or and decent level of computer literacy.<br>13. Oversea graduated also bonus</p>','<p>1. Reminder of daily weekly meeting and schedules.<br>2. Take over some of my work while I am away on trips. E.g. if I have construction project. Keep follow up and updates; if I have loan deal, keep follow up and updates.<br>3. Prepare driver when I need to leave or when driver not available drive on behave of driver.<br>4. Prepare meeting minutes<br>5. Make booking and reservation for restaurants, hotel, air ticket and others.<br>6. Have good khmer, English and chinese language speaking reading and writing additional language is bonus.<br>8. High level of organization skills<br>9. Take initiative to make plan or action when think require.<br>10. Thinking level at least business from supervisor level.<br>11. Must look presentable and professional.<br>12. Able to know modern AL ( bonus) or and decent level of computer literacy.<br>13. Oversea graduated also bonus</p>','<ul>\n<li><!-- [if !supportLists]--><span style=\"font-family: \'Trebuchet MS\',sans-serif;\">Bachelor in related field (Law, Banking, Finance, Accounting, ...).</span><span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;</span></li>\n<li><span style=\"font-family: \'Trebuchet MS\',sans-serif;\">At least two years of work experiences.</span></li>\n<li><span style=\"font-family: \'Trebuchet MS\', sans-serif; text-align: justify; text-indent: -18pt;\">Strong analytical and problem-solving skills, with the ability to interpret and apply complex regulations and policies.</span></li>\n<li>Excellent communication and interpersonal skills.</li>\n<li>Ability to work independently, exercise sound judgment, and maintain the highest level of confidentiality and professionalism</li>\n<li>Strong organizational skills, attention to detail, and ability to handle multiple tasks simultaneously.</li>\n</ul>','<ul>\n<li><span style=\"font-family: \'Trebuchet MS\',sans-serif;\">Bachelor in related field (Law, Banking, Finance, Accounting, ...).</span><span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;</span></li>\n<li><span style=\"font-family: \'Trebuchet MS\',sans-serif;\">At least two years of work experiences.</span></li>\n<li><span style=\"font-family: \'Trebuchet MS\', sans-serif; text-align: justify; text-indent: -18pt;\">Strong analytical and problem-solving skills, with the ability to interpret and apply complex regulations and policies.</span></li>\n<li>Excellent communication and interpersonal skills.</li>\n<li>Ability to work independently, exercise sound judgment, and maintain the highest level of confidentiality and professionalism</li>\n<li>Strong organizational skills, attention to detail, and ability to handle multiple tasks simultaneously.</li>\n</ul>','Head Office, Phnom Penh','Head Office, Phnom Penh','2026-04-30','',0,0,'2026-04-18 09:33:31','2026-09-15 09:18:54','pa-to-managing-director','','','','','');
