INSERT INTO `site_settings` VALUES (1,'HOMEPAGE','{\"seo_title_eng\":\"Chhayvann Co.,Ltd | Gold Trading | Money Exchange Rate\",\"seo_title_km\":\"\",\"seo_description_eng\":\"Chhayvann Co.,Ltd, Gold Trading, Money Exchange Rate\",\"seo_description_km\":\"\",\"seo_keywords\":\"Chhayvann Co.,Ltd, Gold Trading, Money Exchange Rate\",\"subtitle\":\"\",\"subtitleKm\":\"\",\"companyName\":\"CHHAYVANN Co., Ltd.\",\"companyNameKm\":\"\\u1780\\u17d2\\u179a\\u17bb\\u1798\\u17a0\\u17ca\\u17bb\\u1793 \\u1786\\u17b6\\u1799\\u179c\\u17c9\\u17b6\\u1793\\u17cb \\u1781\\u17bc \\u17a2\\u17b7\\u179b\\u1792\\u17b8\\u178c\\u17b8\",\"aboutCompany\":\"<div>\\n<p>Welcome to <strong>CHHAYVANN Co., Ltd.<\\/strong>, a leading company in Cambodia\'s gold trading industry. We specialize in high-quality wholesale trading, retail services, financing, and wealth preservation services, all built on a strong foundation of trust, quality, and professionalism.<\\/p>\\n<p>We are deeply honored and delighted that you have chosen CHHAYVANN Co., Ltd. as your trusted business partner for gold trading. Whether you require gold in large quantities for business purposes or smaller amounts for personal use, we are always ready to deliver quality products at competitive prices, supported by prompt, reliable, and professional service.<\\/p>\\n<p>At CHHAYVANN Co., Ltd., customer trust is at the heart of everything we do. We are dedicated to delivering transparent, secure, and innovative services that meet the evolving needs of our customers while building strong and lasting relationships with our clients and business partners. We look forward to growing together and achieving lasting success through a strong and valued partnership.<\\/p>\\n<p>Thank you for your trust and support.<\\/p>\\n<\\/div>\",\"aboutCompanyKm\":\"<p>\\u179f\\u17bc\\u1798\\u179f\\u17d2\\u179c\\u17b6\\u1782\\u1798\\u1793\\u17cd\\u1799\\u17c9\\u17b6\\u1784\\u1780\\u1780\\u17cb\\u1780\\u17d2\\u178f\\u17c5\\u1798\\u1780\\u1780\\u17b6\\u1793\\u17cb \\u1780\\u17d2\\u179a\\u17bb\\u1798\\u17a0\\u17ca\\u17bb\\u1793 \\u1786\\u17b6\\u1799\\u179c\\u17c9\\u17b6\\u1793\\u17cb \\u1781\\u17bc \\u17a2\\u17b7\\u179b\\u1792\\u17b8\\u178c\\u17b8 \\u178a\\u17c2\\u179b\\u1787\\u17b6\\u1780\\u17d2\\u179a\\u17bb\\u1798\\u17a0\\u17ca\\u17bb\\u1793\\u1788\\u17b6\\u1793\\u1798\\u17bb\\u1781\\u1782\\u17c1\\u1780\\u17d2\\u1793\\u17bb\\u1784\\u179c\\u17b7\\u179f\\u17d0\\u1799\\u1787\\u17bd\\u1789\\u178a\\u17bc\\u179a\\u1798\\u17b6\\u179f\\u1793\\u17c5\\u1794\\u17d2\\u179a\\u1791\\u17c1\\u179f\\u1780\\u1798\\u17d2\\u1796\\u17bb\\u1787\\u17b6 \\u178a\\u17c4\\u1799\\u1795\\u17d2\\u178f\\u179b\\u17cb\\u1787\\u17bc\\u1793\\u1793\\u17bc\\u179c\\u179f\\u17c1\\u179c\\u17b6\\u1780\\u1798\\u17d2\\u1798 \\u1787\\u17bd\\u1789\\u178a\\u17bc\\u179a\\u1794\\u17c4\\u17c7\\u178a\\u17bb\\u17c6 \\u179f\\u17c1\\u179c\\u17b6\\u1780\\u1798\\u17d2\\u1798\\u179b\\u1780\\u17cb\\u179a\\u17b6\\u1799 \\u17a0\\u17b7\\u179a\\u1789\\u17d2\\u1789\\u1794\\u17d2\\u1794\\u1791\\u17b6\\u1793 \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u1790\\u17c2\\u179a\\u1780\\u17d2\\u179f\\u17b6\\u1780\\u17b6\\u179a\\u1796\\u17b6\\u179a\\u1791\\u17d2\\u179a\\u1796\\u17d2\\u1799\\u179f\\u1798\\u17d2\\u1794\\u178f\\u17d2\\u178f\\u17b7 \\u1794\\u17d2\\u179a\\u1780\\u1794\\u178a\\u17c4\\u1799\\u1782\\u17bb\\u178e\\u1797\\u17b6\\u1796 \\u1797\\u17b6\\u1796\\u1787\\u17bf\\u1787\\u17b6\\u1780\\u17cb \\u1793\\u17b7\\u1784\\u179c\\u17b7\\u1787\\u17d2\\u1787\\u17b6\\u1787\\u17b8\\u179c\\u17c8\\u17d4<\\/p>\\n<p>\\u1799\\u17be\\u1784\\u1781\\u17d2\\u1789\\u17bb\\u17c6\\u1798\\u17b6\\u1793\\u1780\\u17b7\\u178f\\u17d2\\u178f\\u17b7\\u1799\\u179f \\u1793\\u17b7\\u1784\\u179f\\u17c1\\u1785\\u1780\\u17d2\\u178f\\u17b8\\u179f\\u17c4\\u1798\\u1793\\u179f\\u17d2\\u179f\\u179a\\u17b8\\u1780\\u179a\\u17b6\\u1799\\u1799\\u17c9\\u17b6\\u1784\\u1780\\u17d2\\u179a\\u17c3\\u179b\\u17c2\\u1784 \\u178a\\u17c2\\u179b\\u179b\\u17c4\\u1780\\u17a2\\u17d2\\u1793\\u1780\\u1794\\u17b6\\u1793\\u1787\\u17d2\\u179a\\u