INSERT INTO `trading_videos` VALUES (1,'www.youtube.com/watch?v=tlnct-bP46Y','/sites-settings/Chhayvann_NnVynvzDKCmpt73IVbJdVXDyyCU6YNFEGk2ljpAc.webp',1,1,'2026-09-04 03:04:01','2026-09-16 03:49:04','HOW TO USE OUR PLATFORM','របៀបប្រើប្រាស់កម្មវិធីរបស់យើង','Easy to Follow Video','វីដេអូងាយស្រួលតាមដាន','Please watch our video to learn how to use the CVG Platform for buying and selling gold, as well as how to trade safely, check live prices, and manage your transactions with confidence by following the step-by-step guide provided in the video.','សូមមើលវីដេអូរបស់យើង ដើម្បីស្វែងយល់អំពីរបៀបប្រើប្រាស់កម្មវិធី CVG ផ្លាតហ្វម សម្រាប់ការទិញ និងលក់មាស ព្រមទាំងស្វែងយល់អំពីរបៀបធ្វើការជួញដូរដោយសុវត្ថិភាព ការពិនិត្យតម្លៃផ្ទាល់ និងការគ្រប់គ្រងប្រតិបត្តិការរបស់អ្នកដោយទំនុកចិត្ត តាមដំណាក់កាលនីមួយៗដែលបានរៀបចំជូននៅក្នុងវីដេអូ។','https://www.youtube.com/watch?v=tlnct-bP46Y'),(2,'https://www.facebook.com/reel/1680876893002431','/sites-settings/Chhayvann_IzBbSfOPvLnGwwBUj9dFqcBbcTCsmpRJ4PWRrWfD.jpg',2,0,'2026-09-04 03:07:11','2026-09-10 01:54:02','HOW TO USE OUR PLATFORM','របៀបប្រើប្រាស់កម្មវិធីរបស់យើង','Easy to Follow Video','វីដេអូងាយស្រួលតាមដាន','Watch our videos to understand how to use the CHHAYVANN Co., Ltd.’s platform for physical gold. Learn step‑by‑step how to trade securely, check live prices, and manage your transactions with confidence.','សូមមើលវីដេអូរបស់យើង ដើម្បីយល់អំពីរបៀបប្រើប្រាស់កម្មវិធីរបស់ក្រុមហ៊ុន ឆាយវ៉ាន់ ខូអិលធីឌី សម្រាប់ការទិញ~លក់ មាស និងប្រាក់។ រៀនជាដំណាក់កាលពីរបៀបធ្វើការជួញដូរដោយសុវត្ថិភាព ពិនិត្យតម្លៃផ្ទាល់ និងគ្រប់គ្រងប្រតិបត្តិការរបស់អ្នកដោយទំនុកចិត្ត។','https://www.facebook.com/reel/1680876893002431');
