INSERT INTO `tradings` VALUES (1,'Step 04','ជំហានទី ៤','Log‑In to Start','ចូលប្រព័ន្ធដើម្បីចាប់ផ្តើម (Log-In to Start)','Once your account is opened, you can log in with your user ID and password to begin buying or selling instantly.','នៅពេលគណនីរបស់អ្នកត្រូវបានបើករួចរាល់ អ្នកអាចចូលប្រើប្រាស់ (Log in) ដោយប្រើ User ID និងពាក្យសម្ងាត់ (Password) របស់អ្នក ដើម្បីចាប់ផ្តើមទិញ ឬលក់បានភ្លាមៗ។','/sites-settings/Chhayvann_SEReUVpGymZrteNIbtAYMG3SkPnaT1jReVzO6HvB.png',1,1,'2026-01-12 21:48:56','2026-08-19 08:43:53','MOBILE'),(2,'Step 03','ជំហានទី ៣','Advisor Assignment','ការចាត់ចែងភ្នាក់ងារលក់ (Advisor Assignment)','Upon successfully opening an account, a customer adviser will be assigned to support and guide you with your trading activities.','នៅពេលលោកអ្នកបើកគណនីប្រើប្រាស់ជោគជ័យ និងមានក្រុមការងារផ្នែកលក់ជួយណែនាំ និងគាំទ្រ សម្រាប់ការធ្វើប្រតិបត្តិការទិញ~លក់។','/sites-settings/Chhayvann_cApuBAxOe1wXpNx1jF9DdpQmkzoQqsrqXpJPpEkv.png',2,1,'2026-01-12 21:49:33','2026-08-29 06:27:38','MOBILE'),(3,'Step 02','ជំហានទី ២','Identity Verification','ការផ្ទៀងផ្ទាត់អត្តសញ្ញាណ (Identity Verification)','The information collected is used solely for identity verification when opening an account: For Individual Accounts: Valid identification is required. For Corporate Accounts: Business registration is required.','ព័ត៌មានដែលប្រមូលបាន គឺប្រើប្រាស់សម្រាប់តែការផ្ទៀងផ្ទាត់អត្តសញ្ញាណនៅពេលបើកគណនីប៉ុណ្ណោះ៖ គណនីបុគ្គល៖ តម្រូវឱ្យមានឯកសារអត្តសញ្ញាណដែលមានសុពលភាព (អត្តសញ្ញាណប័ណ្ណ ឬលិខិតឆ្លងដែន)។ គណនីក្រុមហ៊ុន/ប្រកបអាជីវកម្ម៖ តម្រូវឱ្យមានលិខិតចុះបញ្ជីពាណិជ្ជកម្ម។','/sites-settings/Chhayvann_jz0uZKY8X3xZmQJflDu9dzkXK1ykBwsfqqCgmz8T.png',3,1,'2026-01-12 21:50:09','2026-08-19 08:42:56','MOBILE'),(4,'Step 01','ជំហានទី ១','Know Your Customer (KYC)','ការស្គាល់អតិថិជន (KYC)','As part of our Know Your Customer (KYC) requirements, we may ask customers to provide valid identification documents and, where applicable, business registration. This is to verify identity before establishing a business relationship or processing certain transactions.','ដើម្បីអនុវត្តតាមតម្រូវការនៃការស្គាល់អតិថិជន (KYC) យើងខ្ញុំអាចស្នើសុំឱ្យអតិថិជនផ្តល់ឯកសារអត្តសញ្ញាណប័ណ្ណដែលមានសុពលភាព និងលិខិតចុះបញ្ជីពាណិជ្ជកម្ម (ប្រសិនបើមាន)។ នេះគឺដើម្បីផ្ទៀងផ្ទាត់អត្តសញ្ញាណ មុនពេលចាប់ផ្តើមទំនាក់ទំនងអាជីវកម្ម ឬដំណើរការប្រតិបត្តិការផ្សេងៗ។','/sites-settings/Chhayvann_MuI9rSEWUh47jNngEqdgJGDkDhEqbUFjbk5gNMzg.png',4,1,'2026-01-12 21:50:47','2026-08-19 08:42:24','MOBILE'),(5,'Step 01','ជំហានទី ១','Know Your Customer (KYC)','ការស្គាល់អតិថិជន (KYC)','As part of our Know Your Customer (KYC) requirements, we may ask customers to provide valid identification documents and, where applicable, business registration. This is to verify identity before establishing a business relationship or processing certain transactions.','ដើម្បីអនុវត្តតាមតម្រូវការនៃការស្គាល់អតិថិជន (KYC) យើងខ្ញុំអាចស្នើសុំឱ្យអតិថិជនផ្តល់ឯកសារអត្តសញ្ញាណប័ណ្ណដែលមានសុពលភាព និងលិខិតចុះបញ្ជីពាណិជ្ជកម្ម (ប្រសិនបើមាន)។ នេះគឺដើម្បីផ្ទៀងផ្ទាត់អត្តសញ្ញាណ មុនពេលចាប់ផ្តើមទំនាក់ទំនងអាជីវកម្ម ឬដំណើរការប្រតិបត្តិការផ្សេងៗ។','/sites-settings/Chhayvann_SH9ZjGAh0sIwebqycuHg5SgK8P6B31lUPLAIAdkR.png',4,1,'2026-08-13 07:01:33','2026-09-08 03:59:22','PC'),(6,'Step 02','ជំហានទី ២','Identity Verification','ការផ្ទៀងផ្ទាត់អត្តសញ្ញាណ (Identity Verification)','The information collected is used solely for identity verification when opening an account: For Individual Accounts: Valid identification is required. For Corporate Accounts: Business registration is required.','ព័ត៌មានដែលប្រមូលបាន គឺប្រើប្រាស់សម្រាប់តែការផ្ទៀងផ្ទាត់អត្តសញ្ញាណនៅពេលបើកគណនីប៉ុណ្ណោះ៖ គណនីបុគ្គល៖ តម្រូវឱ្យមានឯកសារអត្តសញ្ញាណដែលមានសុពលភាព (អត្តសញ្ញាណប័ណ្ណ ឬលិខិតឆ្លងដែន)។ គណនីក្រុមហ៊ុន/ប្រកបអាជីវកម្ម៖ តម្រូវឱ្យមានលិខិតចុះបញ្ជីពាណិជ្ជកម្ម។','/sites-settings/Chhayvann_RwWUHy6XCXanEXCfunwILtoJhEfvsjZJ8lPdsgvm.png',3,1,'2026-08-13 07:02:57','2026-09-06 06:57:59','PC'),(7,'Step 03','ជំហានទី ៣','Advisor Assignment','ការចាត់ចែងភ្នាក់ងារលក់ (Advisor Assignment)','Upon successfully opening an account, a customer adviser will be assigned to support and guide you with your trading activities.','នៅពេលលោកអ្នកបើកគណនីប្រើប្រាស់ជោគជ័យ និងមានក្រុមការងារផ្នែកលក់ជួយណែនាំ និងគាំទ្រ សម្រាប់ការធ្វើប្រតិបត្តិការទិញ~លក់។','/sites-settings/Chhayvann_TOZuLbX4SznW5Eeoyjl7LUqDFgLDy4BlsCctqjGh.png',2,1,'2026-08-18 08:25:21','2026-09-06 06:58:12','PC'),(9,'Step 04','ជំហានទី ៤','Log‑In to Start','ចូលប្រព័ន្ធដើម្បីចាប់ផ្តើម (Log-In to Start)','Once your account is opened, you can log in with your user ID and password to begin buying or selling instantly.','នៅពេលគណនីរបស់អ្នកត្រូវបានបើករួចរាល់ អ្នកអាចចូលប្រើប្រាស់ (Log in) ដោយប្រើ User ID និងពាក្យសម្ងាត់ (Password) របស់អ្នក ដើម្បីចាប់ផ្តើមទិញ ឬលក់បានភ្លាមៗ។','/sites-settings/Chhayvann_0QIUhuP50kK9BKLIlcW9BYuvcjqmFp6Pdz7Z5yTS.png',1,1,'2026-08-18 08:39:06','2026-09-06 03:36:25','PC');
